-- Voidborn sound items. Every item is referenced by name ("vb_<file>") from unit/weapon defs and widgets.
-- Files are generated by tools/gen_sounds.py into game/sounds/.
--   gain      base volume          pitchmod / gainmod   random variation per play
--   maxconcurrent  cap on simultaneous plays (stops 40 lasers turning into a wall of noise)
--   in3d      false = plays flat (UI / alerts), default true = positioned in the world
local S = {}
local function add(name, gain, extra)
	local t = { file = "sounds/" .. name .. ".wav", gain = gain, pitchmod = 0.06, gainmod = 0.08, maxconcurrent = 6 }
	for k, v in pairs(extra or {}) do t[k] = v end
	S["vb_" .. name] = t
end

local flat = { in3d = false, pitchmod = 0, gainmod = 0, maxconcurrent = 2 }
-- UI
for _, n in ipairs({ "ui_click", "ui_hover", "ui_select", "ui_open", "ui_close", "ui_error", "ui_place" }) do add(n, 0.7, flat) end
add("ui_hover", 0.35, flat)
-- alerts / jingles
add("alarm_commander", 0.9, flat); add("unit_ready", 0.7, flat); add("struct_done", 0.8, flat)
add("game_start", 0.9, flat); add("build_start", 0.7, { maxconcurrent = 3 }); add("nano_zap", 0.45, { maxconcurrent = 3 })
add("split_pop", 0.8, { maxconcurrent = 4 })
-- unit voices
add("select_choir", 0.7, { in3d = false, maxconcurrent = 2 }); add("ok_choir", 0.55, { in3d = false, maxconcurrent = 2 })
add("select_maw", 0.75, { in3d = false, maxconcurrent = 2 });   add("ok_maw", 0.6, { in3d = false, maxconcurrent = 2 })
add("select_struct_choir", 0.6, { in3d = false, maxconcurrent = 2 }); add("select_struct_maw", 0.7, { in3d = false, maxconcurrent = 2 })
-- weapons
add("laser_choir_light", 0.5, { maxconcurrent = 8 }); add("laser_choir", 0.65, { maxconcurrent = 6 }); add("laser_choir_heavy", 0.9, { maxconcurrent = 3 })
add("acid_light", 0.5, { maxconcurrent = 8 }); add("acid_spit", 0.65, { maxconcurrent = 6 }); add("acid_heavy", 0.9, { maxconcurrent = 3 })
add("spore_launch", 0.75, { maxconcurrent = 4 }); add("flame_breath", 0.55, { maxconcurrent = 4 }); add("dgun_blast", 1.0, { maxconcurrent = 2 })
-- impacts
add("hit_laser", 0.5, { maxconcurrent = 8 }); add("hit_acid", 0.5, { maxconcurrent = 8 })
add("boom_small", 0.8, { maxconcurrent = 8 }); add("boom_med", 0.95, { maxconcurrent = 5 }); add("boom_big", 1.0, { maxconcurrent = 3 })
-- economy / structures
add("mex_on", 0.6, { maxconcurrent = 3 }); add("radar_ping", 0.55, { maxconcurrent = 3 })
add("power_on", 0.55, { maxconcurrent = 3 }); add("power_off", 0.5, { maxconcurrent = 3 })

-- commander weapons: persistent beam, acid glob, D-gun / Q-gun per faction, stun-wave impact
add("beam_choir", 0.8, { maxconcurrent = 3 }); add("hit_beam", 0.45, { maxconcurrent = 6 })
add("acid_glob", 0.85, { maxconcurrent = 3 }); add("hit_glob", 0.65, { maxconcurrent = 5 })
add("dgun_choir", 1.0, { maxconcurrent = 2 }); add("dgun_maw", 1.0, { maxconcurrent = 2 })
add("qgun_choir", 0.95, { maxconcurrent = 2 }); add("qgun_maw", 0.95, { maxconcurrent = 2 }); add("stun_wave", 0.9, { maxconcurrent = 3 })
add("gun_ready", 0.7, flat); add("gun_denied", 0.6, flat)
-- announcements (played flat by the vb_sounds widget)
for n, g in pairs({ cloak_on = 0.6, cloak_off = 0.6, commander_lost = 1.0, enemy_commander_down = 0.9, victory = 1.0,
                    defeat = 1.0, energy_low = 0.8, metal_low = 0.8, tier2_ready = 0.9 }) do add(n, g, flat) end

return { SoundItems = S }
